<template>
  <div class="login-container">
    <div class="login-box">
      <h2>登录</h2>
      <form @submit.prevent="login">
        <div class="form-group">
          <label for="email">邮箱</label>
          <input type="email" id="email" v-model="email" required />
        </div>
        <div class="form-group">
          <label for="password">密码</label>
          <input type="password" id="password" v-model="password" required />
        </div>
        <div class="form-group remember-me">
          <input type="checkbox" id="rememberMe" v-model="needRefreshToken" />
          <label for="rememberMe"
          style="position: relative; bottom: -0.21rem;"
          >长时免登录</label>
        </div>
        <button type="submit" class="login-button">登录</button>
        <div class="register-link">
          <a @click="goToRegister"><u>去注册</u></a>
        </div>
      </form>
    </div>
  </div>
</template>

<script>
import { login, postFuncData } from '@/api/user/user_api.js'; // 导入注册方法
import jsCookie from 'js-cookie';

export default {
  data() {
    return {
      email: '',
      password: '',
      needRefreshToken: false,
      ifHaveTokenThenGoTo: "cat"
    };
  },
  mounted() {
    // 页面挂载时，优先使用 access_token 发送请求
    this.checkAccessToken();
  },
  methods: {
    login() {
      // 使用导入的 login 方法发送 POST 请求
      login({
        email: this.email,
        password: this.password,
        need_refresh_token: this.needRefreshToken
      })
        .then(response => {
          console.log('登录成功');
          // 存储 token 到 cookie
          const expires = new Date();
          expires.setDate(expires.getDate() + 30); // 设置过期时间为 30 天
          jsCookie.set('access_token', response.data.access_token, { expires: expires, secure: false, sameSite: 'Strict' });
          jsCookie.set('refresh_token', response.data.refresh_token, { expires: expires, secure: false, sameSite: 'Strict' });
          console.log('token设置成功！');
          // 登录成功后的跳转逻辑
          try {
            this.$router.push({ name: this.ifHaveTokenThenGoTo });
          } catch (error) {
            console.error('路由跳转错误:', error);
          }
        })
        .catch(error => {
          if (error.response) {
            // 从响应数据中获取错误信息
            const errorMessage = error.response.data.trim();
            console.error('登录失败:', errorMessage);
            alert(`登录失败: ${errorMessage}`);
          } else {
            console.error('登录失败:', error.message);
            alert("登录失败");
          }
        })
    },
    checkAccessToken() {
      // 若存在 access_token，则尝试使用它进行请求，成功则立刻离开此界面
      // 使用 access_token 和 refresh_token 发送请求到 postFuncData 测试接口
      postFuncData({})
        .then(() => {
          this.$router.push({ name: this.ifHaveTokenThenGoTo });
        })
        .catch(error => {
          console.error('验证失败，需要重新登录: ', error);
          // 清除过期或无效的 token
          jsCookie.remove('access_token');
          jsCookie.remove('refresh_token');

        });
    },
    goToRegister() {
      try {
        this.$router.push({ name: 'register' });
      } catch (error) {
        console.error('路由跳转错误:', error);
      }
    },
  }
};
</script>

