<template>
    <div class="cat_page_container">
        <div class="CatSideBar">
            <CatSideBar :normalColor="!false" :affValue="affValue" @unlockCatAffection="refresh"/>
        </div>
        <div class="CatWindow">
            <CatBox @catTouched="IncreaseAffValue" :haveThisCat="haveThisCat" />
        </div>
    </div>
</template>

<script>
import CatSideBar from "@/components/CatSideBar.vue";
import CatBox from "@/components/CatBox.vue";
import { touchCat, getACatInfo } from "@/api/cat/cat_api.js";

export default {
    data() {
        return {
            affValue: 0,
            default_cat_id: "1904165251570470912",
            haveThisCat: false,
            // catImage: require('@/assets/cat.svg') // 可以在这里定义小猫的图片路径
        };
    },
    components: {
        CatSideBar,
        CatBox
    },
    mounted() {
        this.GetCatInfo();
    },
    methods: {
        IncreaseAffValue() {
            touchCat({ cat_id: "1904165251570470912" }).then(res => {
                this.affValue += res.data.change_affection_value;
            }).catch(error => {
                console.error('摸猫失败:', error);
            });
        },
        refresh() {
            // 刷新页面
            if (location.href.indexOf("#reloaded") == -1) {
                location.href = location.href + "#reloaded";
                location.reload();
            }
        },
        GetCatInfo() {
            getACatInfo({
                cat_id: this.default_cat_id
            }).then((res) => {
                this.affValue = res.data.affection;
                this.haveThisCat = true
            }).catch(error => {
                console.error('获取猫猫信息失败:', error);
            });
        },
    }
};
</script>

<style scoped>
.CatSideBar {
    width: 13%;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
}

.CatWindow {
    width: 87%;
    height: 100%;
    /* background-color: aquamarine; */
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    position: relative;
    /* 为绝对定位的子元素提供定位上下文 */
}

.cat_page_container {
    width: 100vw;
    height: 100vh;
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    /* background-color: antiquewhite; */
    position: fixed;
    top: 0;
    left: 0;
}
</style>