import axios from 'axios';
import jsCookie from 'js-cookie';

// 创建 axios 实例
const instance = axios.create({
    baseURL: 'http://47.109.156.75:9001', // 统一的域名, 换成对应服务的url
    timeout: 10000, // 请求超时时间/ms
    headers: {
        'Content-Type': 'application/json',
    },
});

const https_secure = false

// 请求拦截器：在发送请求之前添加 token
instance.interceptors.request.use(
    (config) => {
        // 从cookie中获取 token
        const accessToken = jsCookie.get('access_token');
        const refreshToken = jsCookie.get('refresh_token');
        // 将获取的token设置到请求头
        if (accessToken) {
            config.headers.Authorization = `Bearer ${accessToken}`;
        } else {
            config.headers.Authorization = `Bearer wrong_at`;
        }
        
        if (refreshToken) {
            config.headers['Refresh-Token'] = `${refreshToken}`;
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

// 响应拦截器：处理响应中的 new_access_token
instance.interceptors.response.use(
    (response) => {
        // 检查响应头中是否有 new_access_token
        const newAccessToken = response.headers['new_access_token'];
        if (newAccessToken) {
            // 更新 cookie 中的 access_token
            jsCookie.set('access_token', newAccessToken, {
                expires: 7, // 设置过期时间
                secure: https_secure, // 如果使用 HTTPS
                sameSite: 'Strict'
            });
        }
        // 成功设置access_token后不再重复发起请求
        return response;
    },
    (error) => {
        if (error.response) {
            // 检查响应头中是否有 new_access_token
            const newAccessToken = error.response.headers['new_access_token'];
            if (newAccessToken) {
                // 更新 cookie 中的 access_token
                jsCookie.set('access_token', newAccessToken, {
                    expires: 7, // 设置过期时间
                    secure: https_secure, // 如果使用 HTTPS
                    sameSite: 'Strict'
                });

                // 重新发送原始请求
                const config = error.config;
                config.headers.Authorization = `Bearer ${newAccessToken}`;
                return instance(config);
            }

            // 处理响应错误(开发时使用)
            // console.error('请求失败:', error.response.data);
        } else {
            console.error('请求失败');
        }
        return Promise.reject(error);
    }
);

// 导出常用的请求方法

export const getACat = (data) => {
    return instance.post('/cat/getACat', data);
};

export const getACatInfo = (data) => {
    return instance.post('cat/getACatInfo', data);
};

export const touchCat = (data) => {
    return instance.post('cat/touchCat', data);
};

