<template>
  <div class="cat-container" ref="container">
    <!-- 将父容器的宽度以 rem 为单位传递给子组件 -->
    <catmodel :maxX="containerWidthInRem" :haveThisCat="haveThisCat" @on-click="touchCat" class="cat-model" />
    <!-- 取消注释以添加第二个猫模型 -->
    <!-- <catmodel :maxX="containerWidthInRem" class="cat-model"/> -->
  </div>
</template>

<script>
import catmodel from "@/components/CatModel.vue";

export default {
  components: {
    catmodel
  },
  data() {
    return {
      containerWidth: 0,
    };
  },
  props:{
    haveThisCat:{
      type: Boolean,
      default: false
    }
  },
  computed: {
    // 将像素值转换为 rem 单位
    containerWidthInRem() {
      // 假设根元素的字体大小为 16px（默认值）
      const rootFontSize = parseFloat(getComputedStyle(document.documentElement).fontSize);
      return this.containerWidth / rootFontSize;
    }
  },
  mounted() {
    this.updateContainerSize();
    window.addEventListener('resize', this.updateContainerSize);
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.updateContainerSize);
  },
  methods: {
    touchCat() {
      this.$emit("catTouched")
      // console.log("box have")
    },
    
    updateContainerSize() {
      this.containerWidth = this.$refs.container ? this.$refs.container.offsetWidth : 0;
      // console.log('Container width in pixels:', this.containerWidth);
      // console.log('Container width in rem:', this.containerWidthInRem);
    }
  }
};
</script>

<style scoped>
.cat-container {
  border-radius: 1rem;
  position: fixed;
  height: 90vh;
  width: 80vw;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: flex-end;
  border: 0.1rem solid rgba(0, 0, 0, 0.234);
  box-sizing: border-box;
}

.cat-model {
  position: absolute;
}
</style>