<template>
  <div class="register-container">
    <div class="register-box">
      <h2>邮箱注册</h2>
      <form @submit.prevent="register">
        <div class="form-group">
          <label for="username">用户名</label>
          <input type="text" id="username" v-model="username" required />
        </div>
        <div class="form-group">
          <label for="email">邮箱</label>
          <input type="email" id="email" v-model="email" required />
        </div>
        <div class="form-group">
          <label for="password">密码</label>
          <input type="password" id="password" v-model="password" required />
        </div>
        <div class="form-group">
          <label for="confirmPassword">确认密码</label>
          <input type="password" id="confirmPassword" v-model="confirmPassword" required />
        </div>
        <button type="submit" class="register-button">注册</button>
      </form>
      <div class="register-link">
        <a @click="goToLogin"><u>去登录</u></a>
      </div>
    </div>
  </div>
</template>

<script>
import { register } from '@/api/user/register_api.js'; // 导入注册方法
import jsCookie from 'js-cookie';

export default {
  data() {
    return {
      username: '',
      email: '',
      password: '',
      confirmPassword: ''
    };
  },
  methods: {
    register() {
      if (this.password !== this.confirmPassword) {
        alert("密码和确认密码不一致");
      } else {
        // 调用统一的注册方法
        register({
          username: this.username,
          password: this.password,
          email: this.email
        })
          .then(() => {
            alert("注册成功");
            jsCookie.remove('access_token');
            jsCookie.remove('refresh_token');
            this.goToLogin();
          })
          .catch(error => {
            let errorMessage = '注册失败';
            if (error.response) {
              // 从响应数据中获取错误信息
              errorMessage = error.response.data ? error.response.data.trim() : '服务器返回空数据';
            } else if (error.request) {
              // 请求已发送，但未收到响应
              errorMessage = '请求已发送，但未收到响应';
            } else {
              // 其他错误
              errorMessage = `注册失败: ${error.message}`;
            }
            alert(errorMessage);
            console.error('注册失败:', errorMessage);
          });
      }
    },
    goToLogin() {
      try {
        this.$router.push({ name: 'login' });
      } catch (error) {
        console.error('路由跳转错误:', error);
      }
    }
  }
};
</script>

<style scoped>
html {
  font-size: 16px;
}

body {
  margin: 0;
  padding: 0;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  position: fixed;
  top: 0;
  left: 0;
}

.register-container {
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: linear-gradient(135deg, #e0f2f1 0%, #b2ebf2 100%);
  position: fixed;
  top: 0;
  left: 0;
}

.register-box {
  width: 20rem;
  padding: 1rem;
  background-color: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(8px);
  border-radius: 1rem;
  box-shadow: 0 0.5rem 2rem rgba(0, 0, 0, 0.15);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.register-box:hover {
  transform: translateY(-0.2rem);
  box-shadow: 0 0.8rem 3rem rgba(0, 0, 0, 0.2);
}

h2 {
  text-align: center;
  color: #333;
  margin-bottom: 1.2rem;
  font-size: 1.6rem;
  font-weight: 600;
  letter-spacing: 0.05rem;
  width: 100%;
}

.form-group {
  margin-bottom: 1rem;
  width: 100%;
}

label {
  display: block;
  margin-bottom: 0.5rem;
  color: #444;
  font-size: 0.9rem;
  font-weight: 500;
  transition: color 0.3s ease;
  width: 100%;
}

input[type="text"],
input[type="email"],
input[type="password"] {
  width: 16rem;
  padding: 0.8rem 1rem;
  border: 1px solid #ddd;
  border-radius: 0.5rem;
  background-color: rgba(255, 255, 255, 0.8);
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.08);
  font-size: 0.9rem;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="password"]:focus {
  border-color: #4caf50;
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.1), 0 0 0 2px rgba(76, 175, 80, 0.2);
  outline: none;
}

.register-button {
  width: 18rem;
  padding: 0.9rem;
  background-color: #4caf50;
  color: white;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 500;
  transition: background-color 0.3s ease, transform 0.2s ease, box-shadow 0.3s ease;
  margin-top: 1rem;
  box-shadow: 0 0.3rem 0.6rem rgba(0, 0, 0, 0.1);
}

.register-button:hover {
  background-color: #45a049;
  transform: translateY(-0.1rem);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.register-button:active {
  transform: translateY(0);
