<template>
  <div class="cat_model_container" :class="{ flipped: isFlipped }" :style="{
    height: containerHeight + 'vh',
  }" @mousedown="handleMouseDown" @mouseup="handleMouseUp" @mouseleave="handleMouseLeave" v-show="imagesLoaded">
    <!-- <div class="emoji" v-if="isShrinking" :style="{ height: emojiHeight + '%' }">{{ emoji }}</div> -->
    <div class="cat_box" :style="{
      left: flip_axis + 'rem',
    }">
      <!-- 6.后手臂 -->
      <img ref="armImage1" alt="第一条手臂" class="arm" />

      <!-- 5.腿部 -->
      <img ref="legImage1" alt="第一条腿部" class="leg" />
      <img ref="legImage2" alt="第二条腿部" class="leg" />

      <!-- 4.尾巴 -->
      <img ref="tailImage" alt="尾巴" class="tail" />

      <!-- 3.身体 -->
      <img ref="bodyImage" alt="身体" class="body" />

      <!-- 2.前手臂 -->
      <img ref="armImage2" alt="第二条手臂" class="arm" />

      <!-- 1.最上面 -->
      <img ref="headImage" alt="头部" class="head" />
    </div>
  </div>
</template>

<script>
import anime from 'animejs'; // 引入 anime.js
import armImage from '@/assets/arm1.png'; // 引入手臂图片
import bodyImage from '@/assets/body.png'; // 引入身体图片
import headImage from '@/assets/head.png'; // 引入头部图片
import legImage from '@/assets/leg.png'; // 引入腿部图片
import tailImage from '@/assets/tail.png'; // 引入尾巴图片

export default {
  data() {
    return {
      // 新增移动控制相关变量
      flip_axis: -2,
      positionX: 0,        // 水平位置
      moveSpeed: 0.01,      // 移动速度(rem/ms)
      moveDirection: 1,    // 移动方向(1或-1)
      // maxX: 100,           // 最大移动范围(根据容器宽度动态设置)
      isMoving: false,     // 是否正在移动
      flipInterval: null,   // 自动翻转定时器

      containerHeight: 60,
      // 新增加载状态
      imagesLoaded: false,
      totalImages: 6, // 总图片数量
      loadedCount: 0,
      // emojiHeight: 75,
      // emoji: ">v<",
      // isShrinking: false, // 控制 emoji 是否显示
      baseBottomOffset: 0, // 基准底部偏移量，用于统一控制所有元素的垂直位置
      // 动画切换时间范围
      moveTimeRange: [3, 6], // move 动作的时间范围（1到3秒）
      standTimeRange: [6, 12], // stand 动作的时间范围（2到5秒）
      //站立动作缩减
      stand_scale: 3,

      // 移动动画参数
      armRotateAngle: 7, // 手臂旋转角度
      armAnimationDuration: 1500, // 手臂动画持续时间
      headRotateAngle: 0.7, // 头部旋转角度
      headAnimationDuration: 1500, // 头部动画持续时间

      armOffset: 1.3, // 手臂位置偏移量
      headBottomOffset: 6.1, // 头部底部偏移量（基于屏幕底部）
      headLeftOffset: -0.45, // 头部左侧偏移量
      legBottomOffset: 0, // 腿部底部偏移量（基于屏幕底部）
      legLeftOffset: 0.4, // 腿部左侧偏移量
      tailBottomOffset: 5, // 尾巴底部偏移量（基于屏幕底部）
      tailLeftOffset: 2.2, // 尾巴左侧偏移量

      bodyBottomOffset: 4.5, // 身体底部偏移量（基于屏幕底部）
      bodyLeftOffset: 0, // 身体左侧偏移量
      arm1BottomOffset: 4.3, // 第一条手臂底部偏移量（基于屏幕底部）
      arm1LeftOffset: 1.2, // 第一条手臂左侧偏移量
      arm2BottomOffset: 4.3, // 第二条手臂底部偏移量（基于屏幕底部）
      arm2LeftOffset: 1.2, // 第二条手臂左侧偏移量

      verticalMoveDistance: 1.2, // 垂直移动距离（身体和头部同步）
      verticalAnimationDuration: 1500, // 垂直移动动画持续时间
      legRotateAngle: 5, // 腿部旋转角度
      legAnimationDuration: 1500, // 腿部动画持续时间

      legOffset: 0.8, // 腿部位置偏移量
      tailRotateAngle: 10, // 尾巴旋转角度
      tailAnimationDuration: 2000, // 尾巴动画持续时间

      currentAnimation: 'stand', // 当前动画组
      isFlipped: false,
      animationFrame: null, // 用于存储 requestAnimationFrame 的 ID

      animationTimeout: null,
    };
  },
  props: {
    maxX: {
      type: Number,
    },
    haveThisCat: {
      type: Boolean,
      default: false,
    },
  },
  mounted() {
    this.preloadImages();
    this.setupAutoFlip();
  },
  beforeUnmount() {
    // console.log("组件销毁了")
    cancelAnimationFrame(this.animationFrame);
    clearInterval(this.flipInterval);
    clearTimeout(this.animationTimeout);

  },
  methods: {
    // 新增自动翻转逻辑
    setupAutoFlip() {
      // console.log("flip!")
      const getRandomTime = () => Math.random() * 5000 + 3000; // 3-8秒随机间隔
      const flip = () => {
        this.isFlipped = !this.isFlipped;
        this.moveDirection = this.isFlipped ? -1 : 1;
        this.$nextTick(() => {
          this.flipInterval = setTimeout(flip, getRandomTime());
        });
      };
      this.flipInterval = setTimeout(flip, getRandomTime());
    },
    // 新增图片预加载方法
    preloadImages() {
      const images = [
        { ref: 'armImage1', src: armImage },
        { ref: 'armImage2', src: armImage },
        { ref: 'bodyImage', src: bodyImage },
        { ref: 'headImage', src: headImage },
        { ref: 'legImage1', src: legImage },
        { ref: 'legImage2', src: legImage },
        { ref: 'tailImage', src: tailImage }
      ];

      images.forEach(({ ref, src }) => {
        const img = new Image();
        img.onload = () => {
          this.handleImageLoad();
          // 设置到DOM元素
          if (this.$refs[ref]) {
            this.$refs[ref].src = src;
          }
        };
        img.onerror = () => {
          console.error(`Failed to load image: ${src}`);
          this.handleImageLoad();
        };
        img.src = src;
      });
    },
    // 新增图片加载处理
    handleImageLoad() {
      if (++this.loadedCount >= this.totalImages) {
        this.imagesLoaded = true;
        this.initPositions();
        this.$nextTick(() => {
          this.playAnimation(this.currentAnimation);
          this.startAnimationLoop();
        });
      }
    },
    // 提取位置初始化逻辑
    initPositions() {
      // 调整头部位置（基于底部）
      this.$refs.headImage.style.bottom = `${this.headBottomOffset + this.baseBottomOffset}rem`;
      this.$refs.headImage.style.left = `${this.headLeftOffset}rem`;

      // 调整腿部位置（基于底部）
      this.$refs.legImage1.style.bottom = `${this.legBottomOffset + this.baseBottomOffset}rem`;
      this.$refs.legImage1.style.left = `${this.legLeftOffset}rem`;
      this.$refs.legImage2.style.bottom = `${this.legBottomOffset + this.baseBottomOffset}rem`;
      this.$refs.legImage2.style.left = `calc(${this.legLeftOffset}rem + ${this.legOffset}rem)`;

      // 调整尾巴位置（基于底部）
      this.$refs.tailImage.style.bottom = `${this.tailBottomOffset + this.baseBottomOffset}rem`;
      this.$refs.tailImage.style.left = `${this.tailLeftOffset}rem`;

      // 调整身体位置（基于底部）
      this.$refs.bodyImage.style.bottom = `${this.bodyBottomOffset + this.baseBottomOffset}rem`;
      this.$refs.bodyImage.style.left = `${this.bodyLeftOffset}rem`;

      // 调整手臂位置（基于底部）
      this.$refs.armImage1.style.bottom = `${this.arm1BottomOffset + this.baseBottomOffset}rem`;
      this.$refs.armImage1.style.left = `${this.arm1LeftOffset}rem`;
      this.$refs.armImage2.style.bottom = `${this.arm2BottomOffset + this.baseBottomOffset}rem`;
      this.$refs.armImage2.style.left = `${this.arm2LeftOffset}rem`;

      // 在原有样式设置基础上添加
      this.$el.style.position = 'absolute';
      this.$el.style.left = `${this.positionX}rem`;
    },
    handleMouseDown() {
      // this.isShrinking = true;
      if (this.haveThisCat) {
        this.$emit('on-click'); // 发送点击信号
      }
    },
    handleMouseUp() {
      // this.isShrinking = false;
    },
    handleMouseLeave() {
      // this.isShrinking = false;
    },
    playAnimation(animationGroup) {
      this.currentAnimation = animationGroup;
      this.stopAllAnimations(); // 停止所有现有动画

      if (animationGroup === 'move') {
        this.startMovement();
        // 移动动画组
        if (this.$refs.armImage1 && this.$refs.armImage2) {
          this.rotateImage(this.$refs.armImage1, 'right');
          this.rotateImage(this.$refs.armImage2, 'left');
        }
        if (this.$refs.legImage1 && this.$refs.legImage2) {
          this.rotateLeg(this.$refs.legImage1, 'front');
          this.rotateLeg(this.$refs.legImage2, 'back');
        }
        if (this.$refs.bodyImage) {
          this.moveVertical();
        }
        if (this.$refs.headImage) {
          this.rotateHead();
        }
        if (this.$refs.tailImage) {
          this.rotateTail();
        }
      } else {
        this.stopMovement();
        // 站立动画组
        anime.remove([this.$refs.legImage1, this.$refs.legImage2]);

        if (this.$refs.armImage1 && this.$refs.armImage2) {
          this.standArmImage(this.$refs.armImage1, 'right', this.stand_scale);
          this.standArmImage(this.$refs.armImage2, 'left', this.stand_scale);
        }
        if (this.$refs.bodyImage) {
          this.moveVertical();
        }
        if (this.$refs.headImage) {
          this.rotateHead();
        }
        if (this.$refs.tailImage) {
          this.rotateTail();
        }
      }
    },
    // 新增移动控制方法
    startMovement() {
      // console.log('startMovement');
      if (this.isMoving) return;
      this.isMoving = true;

      const animate = () => {
        if (!this.isMoving) return;

        // 计算新位置
        let newX = this.positionX - this.moveSpeed * this.moveDirection;

        // 边界检测
        if (newX <= 0) {
          newX = 0; // 确保不会超出左边界
          this.moveDirection = 1; // 反转方向
        } else if (newX >= this.maxX) {
          newX = this.maxX; // 确保不会超出右边界
          this.moveDirection = -1; // 反转方向
        }

        this.positionX = newX;
        this.$el.style.left = `${newX}rem`;

        this.animationFrame = requestAnimationFrame(animate);
      };

      this.animationFrame = requestAnimationFrame(animate);
    },

    stopMovement() {
      this.isMoving = false;
      cancelAnimationFrame(this.animationFrame);
    },

    stopAllAnimations() {
      // 这里可以添加代码来停止所有动画
      // 例如，可以通过anime的API来停止动画
    },
    startAnimationLoop() {
  const self = this;

  function nextAnimation() {
    // 清除之前的定时器，避免重复设置
    if (self.animationTimeout) {
      clearTimeout(self.animationTimeout);
      self.animationTimeout = null;
    }

    // 随机决定下一个动作及其持续时间
    let nextAction = Math.random() > 0.5 ? 'move' : 'stand';
    const timeRange = nextAction === 'move' ? self.moveTimeRange : self.standTimeRange;
    let duration = Math.floor(Math.random() * (timeRange[1] - timeRange[0]) + timeRange[0]) * 1000;

    // 如果下一个动作与当前动作相同，则重新选取直到不同或达到一定尝试次数
    let attempts = 0;
    while (nextAction === self.currentAnimation && attempts < 10) { // 设置最大尝试次数防止无限循环
      nextAction = Math.random() > 0.5 ? 'move' : 'stand';
      attempts++;
    }

    if (nextAction !== self.currentAnimation) { // 确保动作确实改变了才执行下面的操作
      // 停止当前所有动画
      self.stopAllAnimations();

      // 播放当前动画
      self.playAnimation(nextAction);

      // 发出当前动画参数
      self.$emit('animation_change', { currentAnimation: nextAction, duration });
    } else {
      console.log("Failed to change action after several attempts.");
    }

    // 设置下一次动画的定时器
    self.animationTimeout = setTimeout(() => {
      nextAnimation();
    }, duration);
  }

  // 开始动画循环
  nextAnimation();
},
    rotateImage(imgRef, position) {
      if (!imgRef) {
        console.error('imgRef is null in rotateImage');
        return;
      }

      // 根据位置调整手臂的初始位置
      if (position === 'left') {
        imgRef.style.left = `calc(2rem - 1.5rem + ${this.armOffset}rem)`; // 微微偏左侧并调整偏移
      } else {
        imgRef.style.left = `${this.armOffset}rem`; // 默认位置并调整偏移
      }

      // 使用 anime.js 创建旋转动画
      anime({
        targets: imgRef, // 目标元素
        rotate: [
          { value: position === 'right' ? -this.armRotateAngle : this.armRotateAngle, duration: this.armAnimationDuration },
          { value: position === 'right' ? this.armRotateAngle : -this.armRotateAngle, duration: this.armAnimationDuration },
        ],
        translateY: [
          { value: -this.verticalMoveDistance, duration: this.verticalAnimationDuration },
          { value: this.verticalMoveDistance, duration: this.verticalAnimationDuration },
        ],
        direction: 'alternate', // 往返动画
        loop: true, // 无限循环
        easing: 'easeInOutQuad', // 缓动效果
        transformOrigin: '50% 0%', // 以图片顶部中心为中心旋转
      });
    },
    standArmImage(imgRef, position, scale) {
      if (!imgRef) {
        console.error('imgRef is null in standArmImage');
        return;
      }

      // 根据位置调整手臂的初始位置
      if (position === 'left') {
        imgRef.style.left = `calc(2rem - 1.5rem + ${this.armOffset}rem)`; // 微微偏左侧并调整偏移
      } else {
        imgRef.style.left = `${this.armOffset}rem`; // 默认位置并调整偏移
      }

      // 使用 anime.js 创建旋转动画
      anime({
        targets: imgRef, // 目标元素
        rotate: [
          { value: position === 'right' ? -this.armRotateAngle / scale : this.armRotateAngle / scale, duration: this.armAnimationDuration },
          { value: position === 'right' ? this.armRotateAngle / scale : -this.armRotateAngle / scale, duration: this.armAnimationDuration },
        ],
        translateY: [
          { value: -this.verticalMoveDistance, duration: this.verticalAnimationDuration },
          { value: this.verticalMoveDistance, duration: this.verticalAnimationDuration },
        ],
        direction: 'alternate', // 往返动画
        loop: true, // 无限循环
        easing: 'easeInOutQuad', // 缓动效果
        transformOrigin: '50% 0%', // 以图片顶部中心为中心旋转
      });
    },
    moveVertical() {
      if (!this.$refs.bodyImage) {
        console.error('bodyImage ref is null in moveVertical');
        return;
      }

      anime({
        targets: [this.$refs.bodyImage], // 目标元素
        translateY: [
          { value: -this.verticalMoveDistance, duration: this.verticalAnimationDuration },
          { value: this.verticalMoveDistance, duration: this.verticalAnimationDuration },
        ],
        direction: 'alternate', // 往返动画
        loop: true, // 无限循环
        easing: 'easeInOutQuad', // 缓动效果
      });
    },
    rotateHead() {
      if (!this.$refs.headImage) {
        console.error('headImage ref is null in rotateHead');
        return;
      }

      // 使用 anime.js 创建头部旋转动画
      anime({
        targets: this.$refs.headImage, // 目标元素
        rotate: [
          { value: -this.headRotateAngle, duration: this.headAnimationDuration },
          { value: this.headRotateAngle, duration: this.headAnimationDuration },
        ],
        translateY: [
          { value: -this.verticalMoveDistance, duration: this.verticalAnimationDuration },
          { value: this.verticalMoveDistance, duration: this.verticalAnimationDuration },
        ],
        direction: 'alternate', // 往返动画
        loop: true, // 无限循环
        easing: 'easeInOutQuad', // 缓动效果
        transformOrigin: '50% 100%', // 以图片底部中心为中心旋转
      });
    },
    rotateLeg(imgRef, position) {
      if (!imgRef) {
        console.error('imgRef is null in rotateLeg');
        return;
      }

      // 根据位置调整腿部的初始位置
      if (position === 'back') {
        imgRef.style.left = `calc(${this.legLeftOffset}rem + ${this.legOffset}rem)`; // 微微偏右侧并调整偏移
      } else {
        imgRef.style.left = `${this.legLeftOffset}rem`; // 默认位置并调整偏移
      }

      // 使用 anime.js 创建旋转动画
      anime({
        targets: imgRef, // 目标元素
        rotate: [
          { value: position === 'front' ? -this.legRotateAngle : this.legRotateAngle, duration: this.legAnimationDuration },
          { value: position === 'front' ? this.legRotateAngle : -this.legRotateAngle, duration: this.legAnimationDuration },
        ],
        direction: 'alternate', // 往返动画
        loop: true, // 无限循环
        easing: 'easeInOutQuad', // 缓动效果
        transformOrigin: '50% 0%', // 以图片顶部中心为中心旋转
      });
    },
    rotateTail() {
      if (!this.$refs.tailImage) {
        console.error('tailImage ref is null in rotateTail');
        return;
      }

      // 使用 anime.js 创建尾巴旋转动画
      anime({
        targets: this.$refs.tailImage, // 目标元素
        rotate: [
          { value: -this.tailRotateAngle, duration: this.tailAnimationDuration },
          { value: this.tailRotateAngle, duration: this.tailAnimationDuration },
        ],
        direction: 'alternate', // 往返动画
        loop: true, // 无限循环
        easing: 'easeInOutQuad', // 缓动效果
        transformOrigin: '0% 50%', // 以图片左侧中心为中心旋转
      });
    },
  },
};
</script>

<style scoped>
/* 可选样式，调整图片大小等 */
html {
  font-size: 16px;
}

/* 确保所有元素都设置了 position: relative 或 absolute */
.head,
.arm,
.body,
.leg,
.tail {
  position: absolute;
  user-select: none;
  /* 禁止选中 */
  -webkit-user-drag: none;
  /* 禁止拖动 */
  -webkit-touch-callout: none;
  /* iOS Safari */
  -webkit-user-select: none;
  /* Chrome/Safari/Opera */
  -khtml-user-select: none;
  /* Konqueror */
  -moz-user-select: none;
  /* Firefox */
  -ms-user-select: none;
  /* Internet Explorer/Edge */
  user-select: none;
  /* Non-prefixed version, currently not supported by any browser */
}

.cat_model_container {
  position: relative;
  height: 60vh;
  /* 使用vh单位控制高度 */
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  user-select: none;
  /* 禁止选中 */
}

/* 点击时向上移动 */
/* .cat_model_container:active {
  
} */

/* .emoji {
  position: absolute;
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  color: pink;
  user-select: none;
} */

.cat_box {
  position: relative;
  height: 30%;
  width: 100%;
  transition: all 0.3s ease;
}

.cat_box:active {
  transform: translateY(-2rem);
  /* 向上移动20px */
}

.head {
  width: 4.2rem;
  height: auto;
  /* position: absolute; */
  transform-origin: 50% 100%;
  /* 确保旋转中心点正确 */
  transform-box: fill-box;
  /* 明确变换的参考点 */
  will-change: transform;
  /* 提示浏览器优化渲染 */
  /* z-index: 100; */
  bottom: 0;
  /* 基于底部 */
}

.arm {
  width: 1.9rem;
  height: auto;
  /* position: absolute; */
  bottom: 0.2rem;
  /* 基于底部 */
  /* transform-origin: 50% 0%; */
  /* 确保旋转中心点正确 */
  transform-box: fill-box;
  /* 明确变换的参考点 */
  will-change: transform;
  /* 提示浏览器优化渲染 */
}

.body {
  width: 3rem;
  height: auto;
  position: absolute;
  bottom: 0rem;
  /* 基于底部 */
  left: 0;
  transform-origin: 50% 50%;
  /* 确保移动的基准点正确 */
  transform-box: fill-box;
  /* 明确变换的参考点 */
  will-change: transform;
  /* 提示浏览器优化渲染 */
}

.leg {
  width: 2rem;
  height: auto;
  position: absolute;
  transform-origin: 50% 0%;
  /* 确保旋转中心点正确 */
  transform-box: fill-box;
  /* 明确变换的参考点 */
  will-change: transform;
  /* 提示浏览器优化渲染 */
  /* z-index: -2; */
  bottom: 0;
  /* 基于底部 */
}

.tail {
  width: 3rem;
  height: auto;
  position: absolute;
  transform-origin: 0% 50%;
  /* 以图片左侧中心为中心旋转 */
  transform-box: fill-box;
  /* 明确变换的参考点 */
  will-change: transform;
  /* 提示浏览器优化渲染 */
  /* z-index: -3; */
  bottom: 0;
  /* 基于底部 */
}

.flipped {
  transform: scaleX(-1);
  /* 水平反转 */
}
</style>